/*
 * Д-36. Возражения относительно исполнения судебного приказа (заявление об отмене судебного приказа).
 * Основа: ст. 128 ГПК (10 дней со дня получения копии приказа), ч. 1 ст. 129 (при поступлении возражений в срок судья
 * отменяет приказ), ч. 2 ст. 129 (возражения после срока рассматриваются, если должник обосновал невозможность подать их
 * вовремя по независящим от него причинам), ч. 3 ст. 107 (в сроки в днях не включаются нерабочие дни), ч. 3 ст. 108
 * (срок соблюдён, если документ сдан на почту до 24 часов последнего дня); ППВС № 62 от 27.12.2016: п. 32 (срок — со дня
 * получения копии или истечения срока хранения письма), п. 33–34 (уважительные причины и документы; подать в течение
 * 10 дней после того, как причины отпали), п. 35 (поворот исполнения, если взыскатель не подал иск);
 * п. 4 ч. 2 ст. 43 Закона № 229-ФЗ (исполнительное производство прекращается при отмене судебного акта).
 * Возражения мотивировать не обязательно. Статус: ЧЕРНОВИК, не проверен юристом.
 */
(function (global) {
  "use strict";
  const { U } = global.Engine;
  const C = global.Common;
  const F = U.F;

  const REASONS = {
    elsewhere: "не проживал(а) по адресу, куда направлялась копия приказа",
    hospital: "находился(ась) на лечении",
    trip: "находился(ась) в командировке",
    vacation: "находился(ась) в отпуске за пределами места жительства",
    post: "почтовое извещение мне не доставлялось, правила доставки судебной корреспонденции были нарушены",
    other: "по иным причинам, не зависящим от меня",
  };
  const OBJECTIONS = {
    not_mine: "я не заключал(а) с взыскателем (его правопредшественником) договор, на котором основано требование, либо не получал(а) денежные средства",
    amount: "я не согласен(на) с размером взыскиваемой суммы",
    paid: "задолженность погашена полностью или частично",
    limitation: "по требованию истёк срок исковой давности",
    assign: "мне не известно о переходе права требования к взыскателю",
  };

  function derive(a) {
    const got = U.date(a.got_date);
    const deadline = got ? C.addWorkdays(got, 10) : null;
    const today = U.today();
    const late = a.got_how === "copy" && !!(deadline && today > deadline);
    // копию не получал: срок по ч. 2 ст. 129 — 10 дней после того, как узнал; обоснование нужно всегда
    const needReasons = a.got_how === "learned" || late;
    const tooLate = a.got_how === "learned" && !!(deadline && today > deadline);
    return { got, deadline, today, late, needReasons, tooLate, calOk: C.calCovers(got) && C.calCovers(deadline) };
  }

  const spec = {
    id: "d36",
    code: "Д-36",
    title: "Возражения на судебный приказ",
    lead: "Мировой судья выдал судебный приказ о взыскании с вас долга без заседания. Возражения в срок отменяют приказ без объяснения причин. Займёт около 5 минут.",
    status: "draft",
    actual: "08.11.2026",

    steps: [
      {
        id: "order", title: "Приказ",
        questions: [
          { id: "court", type: "text", label: "Кто вынес приказ", hint: "Скопируйте из приказа, как есть", placeholder: "Мировой судья судебного участка № 123 района Хамовники г. Москвы" },
          { id: "court_address", type: "text", label: "Адрес судебного участка", required: false, hint: "Есть на сайте участка или в письме суда" },
          { id: "case_no", type: "text", label: "Номер дела", placeholder: "2-1234/2026" },
          { id: "order_date", type: "date", label: "Дата судебного приказа" },
          { id: "creditor", type: "text", label: "Взыскатель", placeholder: "ООО ПКО «Долговой центр»" },
          { id: "sum", type: "money", label: "Какую сумму взыскали по приказу?", suffix: "₽", min: 1, required: false, hint: "Всего, с госпошлиной" },
          { id: "got_how", type: "choice", label: "Как вы узнали о приказе?", options: [
            { value: "copy", label: "Получил(а) копию приказа", hint: "Письмом из суда или лично в суде" },
            { value: "learned", label: "Копию не получал(а) — узнал(а) иначе", hint: "Списали деньги, пришло сообщение от приставов, увидел(а) на Госуслугах" },
          ] },
          { id: "got_date", type: "date", label: "Когда получили копию?", show: a => a.got_how === "copy",
            hint: "Если письмо пролежало на почте и вернулось в суд, срок считается со дня окончания хранения" },
          { id: "got_date", type: "date", label: "Когда узнали о приказе?", show: a => a.got_how === "learned" },
          { id: "reason", type: "select", label: "Почему не получили копию или не успели подать возражения?", show: (a, d) => d.needReasons,
            options: Object.entries(REASONS).map(([value, label]) => ({ value, label: label[0].toUpperCase() + label.slice(1) })) },
          { id: "reason_desc", type: "textarea", label: "Коротко, где вы были и в какие даты", show: (a, d) => d.needReasons,
            placeholder: "С 01.07.2026 по 15.09.2026 жил(а) и работал(а) в г. Казани по адресу: …" },
          { id: "proofs", type: "textarea", label: "Какие документы это подтверждают?", show: (a, d) => d.needReasons,
            hint: "Каждый с новой строки. Суд примет возражения после срока, только если приложить доказательства",
            placeholder: "Копия договора аренды квартиры в г. Казани\nСправка с места работы" },
        ],
      },
      {
        id: "why", title: "Возражения",
        questions: [
          { id: "objections", type: "multi", label: "С чем вы не согласны?", required: false,
            hint: "Можно ничего не выбирать: для отмены приказа достаточно заявить, что вы не согласны. Причины пригодятся, если взыскатель потом подаст иск",
            options: Object.entries(OBJECTIONS).map(([value, label]) => ({ value, label: label[0].toUpperCase() + label.slice(1) })) },
          { id: "withheld", type: "choice", label: "С вас уже что-то списали по этому приказу?", options: [
            { value: "no", label: "Нет" },
            { value: "yes", label: "Да, списали деньги" },
          ] },
        ],
      },
      {
        id: "you", title: "Вы",
        questions: [
          { id: "buyer_name", type: "text", label: "Ваши фамилия, имя и отчество", autocomplete: "name" },
          { id: "buyer_birth", type: "date", label: "Дата рождения", required: false, hint: "Помогает суду быстрее найти дело" },
          { id: "buyer_address", type: "text", label: "Ваш адрес для писем суда", hint: "Если живёте не по регистрации — адрес, где действительно получаете почту", autocomplete: "street-address" },
          { id: "buyer_phone", type: "tel", label: "Телефон", autocomplete: "tel" },
          { id: "buyer_email", type: "email", label: "Электронная почта", required: false, autocomplete: "email" },
        ],
      },
    ],

    derive,

    render(a, d) {
      const P = [];
      const T = t => P.push({ text: t, indent: true });
      const birth = U.date(a.buyer_birth);
      P.push({ text: `${F(a.court, "мировой судья судебного участка №")}` + (a.court_address ? `\nАдрес: ${a.court_address}` : ""), align: "left", leftIndent: 4500, after: 120 });
      P.push({ text: `Должник: ${F(a.buyer_name, "ваши ФИО")}` + (birth ? `, ${U.fmtDate(birth)} г. р.` : "") + `\nАдрес: ${F(a.buyer_address, "адрес")}\nТел.: ${F(a.buyer_phone, "телефон")}` + (a.buyer_email ? `, e-mail: ${a.buyer_email}` : ""), align: "left", leftIndent: 4500, after: 120 });
      P.push({ text: `Взыскатель: ${F(a.creditor, "взыскатель")}`, align: "left", leftIndent: 4500, after: 120 });
      P.push({ text: `Дело № ${F(a.case_no, "номер дела")}`, align: "left", leftIndent: 4500, after: 360 });
      C.title(P, "ВОЗРАЖЕНИЯ", "относительно исполнения судебного приказа");

      T(`${F(U.fmtDate(U.date(a.order_date)), "дата")} по делу № ${F(a.case_no, "номер")} вынесен судебный приказ о взыскании с меня в пользу ${F(a.creditor, "взыскатель")}` + (typeof a.sum === "number" ? ` денежных средств в общей сумме ${U.money(a.sum)} руб.` : " денежных средств.") );
      if (a.got_how === "copy") T(`Копию судебного приказа я получил(а) ${F(U.fmtDate(d.got), "дата")}.`);
      else if (a.got_how === "learned") T(`Копию судебного приказа я не получал(а). О вынесении судебного приказа мне стало известно ${F(U.fmtDate(d.got), "дата")}.`);

      const obj = (a.objections || []).map(k => OBJECTIONS[k]).filter(Boolean);
      T("С судебным приказом я не согласен(на) и возражаю относительно его исполнения" + (obj.length ? ", так как:" + obj.map(x => `\n— ${x};`).join("").replace(/;$/, ".") : "."));
      if (obj.length) T("Требование взыскателя не является бесспорным и подлежит рассмотрению в порядке искового производства.");

      if (d.needReasons) {
        T(`Возражения не могли быть представлены в установленный ст. 128 ГПК РФ срок по причинам, не зависящим от меня: ${a.reason ? REASONS[a.reason] : F(null, "причина")}` + (a.reason_desc ? `. ${String(a.reason_desc).trim().replace(/\.$/, "")}.` : ".") + (a.got_how === "learned" && !d.tooLate ? ` О судебном приказе мне стало известно ${F(U.fmtDate(d.got), "дата")}, возражения подаю в течение десяти дней с этого дня.` : "") + ` Подтверждающие документы прилагаю (ч. 2 ст. 129 ГПК РФ; пп. 33, 34 постановления Пленума Верховного Суда РФ от 27.12.2016 № 62).`);
      }

      P.push({ text: "На основании ст. 128, 129 Гражданского процессуального кодекса РФ", indent: true, keepNext: true });
      P.push({ text: "ПРОШУ:", indent: true, keepNext: true });
      const items = [];
      if (d.needReasons) items.push("Признать причины пропуска срока представления возражений не зависящими от меня и принять настоящие возражения к рассмотрению.");
      items.push(`Отменить судебный приказ от ${F(U.fmtDate(U.date(a.order_date)), "дата")} по делу № ${F(a.case_no, "номер")}.`);
      items.push(`Копию определения об отмене судебного приказа направить мне по адресу: ${F(a.buyer_address, "адрес")}.`);
      items.forEach((x, i) => T(`${i + 1}. ${x}`));
      const att = [];
      if (d.needReasons) String(a.proofs || "").split("\n").map(s => s.trim()).filter(Boolean).forEach(x => att.push(x));
      C.attachments(P, att);
      C.sign(P, a);
      return P;
    },

    guidance(a, d) {
      const g = [];
      const dl = d.deadline ? U.fmtDate(d.deadline) : null;
      if (a.got_how === "copy" && !d.late && dl) g.push({ title: `Подайте не позднее ${dl}.`, text: `Это 10 рабочих дней со дня получения копии (ст. 128, ч. 3 ст. 107 ГПК)${d.calOk ? ", с учётом праздников" : ""}. Если отправляете почтой, срок соблюдён, когда письмо сдано до 24:00 последнего дня.` });
      if (a.got_how === "learned" && dl) g.push({ title: `Подайте как можно скорее — не позднее ${dl}.`, text: "Суд рассмотрит возражения после срока, если подать их в течение 10 рабочих дней после того, как вы узнали о приказе, и приложить доказательства причины." });
      if (d.late) g.push({ title: "Срок уже прошёл — обязательно приложите доказательства.", text: "Без них суд вернёт возражения. Подойдут справка из больницы, командировочное удостоверение, договор аренды в другом городе, отчёт Почты о нарушении доставки." });
      if (d.tooLate) g.push({ title: "С того дня, как вы узнали о приказе, прошло больше 10 рабочих дней.", text: "Суд может вернуть возражения. Тогда остаётся кассационная жалоба в кассационный суд общей юрисдикции. С ней лучше обратиться к юристу." });
      g.push({ title: "Как подать.", text: "Лично в канцелярию судебного участка (возьмите второй экземпляр с отметкой), заказным письмом с описью или в электронном виде через портал ГАС «Правосудие» со входом через Госуслуги." });
      g.push({ title: "После отмены приказа.", text: "Отнесите или отправьте копию определения об отмене приставам: исполнительное производство прекращается (п. 4 ч. 2 ст. 43 Закона № 229-ФЗ). Если деньги списывает банк напрямую по приказу — отдайте копию в банк. Взыскатель может подать иск: тогда спор рассмотрят в обычном заседании, где можно заявить свои доводы." });
      if (a.withheld === "yes") g.push({ title: "Верните списанное — заявление о повороте исполнения.", text: "Его подают тому же мировому судье. Суд вернёт деньги, если взыскатель к этому моменту не подал иск; если подал — вопрос решат в этом деле (ст. 443, 444 ГПК; п. 35 постановления Пленума ВС № 62)." });
      return g;
    },

    reminders(a, d) { return d.tooLate || d.late ? [] : [{ date: d.deadline, title: "Последний день для возражений на судебный приказ", text: "10 рабочих дней с получения копии приказа (ст. 128, 129 ГПК)." }]; },

    fileName(a) { return "Возражения на судебный приказ" + (a.case_no ? " по делу " + String(a.case_no).replace(/[\\/:*?"<>|]/g, "-") : ""); },
  };

  global.DOCS = global.DOCS || {};
  global.DOCS.d36 = spec;
})(typeof window !== "undefined" ? window : globalThis);
